do $runtime_memberships$ begin
if exists(select 1 from pg_auth_members m join pg_roles parent on parent.oid=m.roleid join pg_roles member_role on member_role.oid=m.member join pg_roles grantor on grantor.oid=m.grantor
where (parent.rolname in('sky_guide_sync_reader','sky_guide_sync_writer') or member_role.rolname in('sky_guide_sync_reader','sky_guide_sync_writer'))
and not(parent.rolname in('sky_guide_sync_reader','sky_guide_sync_writer') and member_role.rolname=current_user and m.grantor=10 and grantor.rolsuper and m.admin_option and not m.inherit_option and not m.set_option)) then raise exception 'Runtime memberships require scoped rollback/review';end if;
end;$runtime_memberships$;
